import { Suspense } from "react";
import Link from "next/link";
import { InsightSettings } from "./insights";
import { requireWorkspace } from "@/lib/auth";
import { SkeletonCard } from "@/components/skeleton";
import { SettingsForm } from "./form";
import { SummaryRuns, type SummaryRun } from "./summary-runs";
import { ResetData } from "./reset";
import { AiUsage } from "./ai-usage";
import { AiAccess } from "./ai-access";
import { chatgptStatus } from "@/lib/ai/chatgpt";
import { claudeAccount } from "@/lib/ai/claude";
import { serviceKeyStatus } from "@/lib/service-keys";
import { SetupSecrets } from "./setup-secrets";
import { PhoneAccessSection } from "./phone-access";
import { parseUsageWindow } from "@/lib/ai/usage";
import { cronSecret } from "@/lib/env";
import { awaitedLater } from "@/lib/awaited-later";

export const metadata = { title: "Settings" };

type Workspace = Awaited<ReturnType<typeof requireWorkspace>>;
const card = "scroll-mt-20 rounded-xl border border-border bg-card p-6";
const sectionNav = [
  ["connections", "Keys and connections"], ["display", "Display and calendar"], ["ai", "AI and your data"], ["voice", "Voice"], ["insights", "Insights and summaries"], ["relevance", "Insight relevance"],
  ["summaries", "Scheduled summaries"], ["usage", "AI chat tokens"], ["danger", "Danger zone"],
] as const;

async function loadRuns({ supabase, workspace }: Workspace): Promise<SummaryRun[] | null> {
  const scheduled = await supabase.from("summary_runs").select("id,job_id,cadence,period_start").eq("workspace_id", workspace.id).order("created_at", { ascending: false }).limit(5);
  if (scheduled.error) return null;
  const jobs = scheduled.data.length ? await supabase.from("background_jobs").select("id,status,stage,error").eq("workspace_id", workspace.id).in("id", scheduled.data.map(run => run.job_id)) : null;
  if (jobs?.error) return null;
  return scheduled.data.map(run => {
    const job = jobs?.data?.find(job => job.id === run.job_id);
    return { ...run, status: job?.status ?? "unknown", stage: job?.stage ?? "unavailable", error: job?.error ?? null };
  });
}

type SearchParams = { usage?: string; chatgpt?: string; claude?: string };

export default async function SettingsPage({ searchParams }: { searchParams: Promise<SearchParams> }) {
  const [context, query] = await Promise.all([requireWorkspace(), searchParams]);
  const usageWindow = parseUsageWindow(query.usage);
  const { workspace, settings } = context;
  const runs = awaitedLater(loadRuns(context));
  const [status, keys, claude] = await Promise.all([chatgptStatus(), serviceKeyStatus(), claudeAccount()]);
  const connections = { openai: status.signedIn || Boolean(keys.openai_api_key.source), claude: claude.signedIn, openrouter: Boolean(keys.openrouter_api_key.source) };
  return <main className="mx-auto w-full max-w-[1400px] px-4 py-6 sm:px-8 lg:py-8">
    <div className="flex flex-col gap-1"><p className="eyebrow">Workspace</p><h1 className="page-title">Settings</h1><p className="mt-1 break-words text-sm text-muted-foreground">Your private, self-hosted workspace</p></div>
    <div className="mt-8 grid gap-8 max-lg:mt-4 max-lg:gap-6 lg:grid-cols-[13rem_minmax(0,1fr)]">
      <nav aria-label="Settings sections" className="min-w-0 lg:sticky lg:top-24 lg:self-start">
        <ul className="flex flex-wrap gap-1 max-lg:flex-nowrap max-lg:gap-2 max-lg:overflow-x-auto lg:flex-col [&>li]:shrink-0">{sectionNav.map(([id, label]) => <li key={id}>
          <a href={`#${id}`} className={`block rounded-md px-2.5 py-1.5 text-sm max-lg:rounded-full max-lg:border max-lg:border-border max-lg:bg-card max-lg:px-3.5 max-lg:py-2 hover:bg-muted hover:text-foreground ${id === "danger" ? "text-danger" : "text-muted-foreground"}`}>{label}</a>
        </li>)}</ul>
      </nav>
      <div className="min-w-0 space-y-8">
        <section id="connections" aria-labelledby="connections-title" className="scroll-mt-20 space-y-4">
          <div><h2 id="connections-title" className="text-base font-semibold">Keys and connections</h2>
            <p className="mt-1 text-sm text-muted-foreground">AI keys, phone access and what setup made. Keys are checked before they are saved and stored encrypted in your database; there is no file to edit. Banks and Scalable are connected on <Link href="/money/accounts#connected" className="underline hover:text-foreground">Accounts</Link>.</p></div>
          <AiAccess status={status} keys={keys} claude={claude} message={query.chatgpt} claudeMessage={query.claude} />
          <div id="phone" className="scroll-mt-20"><Suspense fallback={<SkeletonCard lines={2} />}><PhoneAccessSection /></Suspense></div>
          <SetupSecrets />
        </section>
        <SettingsForm settings={settings} aiSource={status.source} connections={connections} currency={workspace.display_currency} timeZones={[...new Set(["UTC", ...Intl.supportedValuesOf("timeZone")])]} />
        <div id="relevance" className="scroll-mt-20"><Suspense fallback={<SkeletonCard lines={4} />}><InsightSettings /></Suspense></div>
        <section id="summaries" className={card}><h2 className="text-sm font-medium">Scheduled summaries</h2>
          <p className="mt-1 text-sm text-muted-foreground">Recent summary runs. Change the schedule under Insights and summaries.</p>
          <details className="mt-2 text-sm text-muted-foreground"><summary className="cursor-pointer">More details</summary><p className="mt-2">Weekly summaries are due on Monday and monthly ones on the first, in your timezone and at your preferred time. A daily check starts due summaries, so they can arrive a day late. Turn summaries off to stop future runs, or stop an active run below.</p></details>
          {!cronSecret() && <p className="mt-3 text-sm text-warning">Automatic scheduling needs to be configured on the deployment. Your preference is saved.</p>}
          <Suspense fallback={<div className="h-10" aria-busy="true" />}><ScheduledRuns runs={runs} locale={settings.locale} /></Suspense>
          <p className="mt-4 text-sm text-muted-foreground">Finished summaries appear in the Activity log. If one fails, run a new review from AI.</p>
        </section>
        <section id="usage" className={card}><h2 className="text-sm font-medium">AI chat token usage</h2><p className="mt-1 text-sm text-muted-foreground">Tokens used by AI chat, per model; other AI tasks are not included. Requests the provider did not report are left out, not counted as zero. Moneo does not record costs: see actual charges with your provider, at <a href="https://platform.openai.com/usage" target="_blank" rel="noreferrer" className="underline hover:text-foreground">OpenAI</a>, <a href="https://claude.ai/settings/usage" target="_blank" rel="noreferrer" className="underline hover:text-foreground">Claude</a> or <a href="https://openrouter.ai/activity" target="_blank" rel="noreferrer" className="underline hover:text-foreground">OpenRouter</a>.</p><Suspense fallback={<SkeletonCard lines={4} />}><AiUsage window={usageWindow} /></Suspense></section>
        <div id="danger" className="scroll-mt-20 space-y-8"><ResetData /></div>
      </div>
    </div>
  </main>;
}

async function ScheduledRuns({ runs, locale }: { runs: Promise<SummaryRun[] | null>; locale: string }) {
  const initial = await runs;
  return initial ? <SummaryRuns initial={initial} locale={locale} /> : <p role="alert" className="mt-3 text-sm text-danger">Scheduled status is unavailable. Try again later.</p>;
}
"use client";

import { useActionState, useEffect, useId, useRef, useState, useSyncExternalStore } from "react";
import { ChevronDown, Loader2, Play, Square } from "lucide-react";
import { CurrencySelect } from "@/components/currency-select";
import { displayFormat } from "@/lib/display-format";
import { AI_AGENT_KEYS, AI_AGENTS, AI_DATA_SCOPES, deviceTimeZone, SPEECH_ENGINES, VOICES } from "@/lib/workspace-settings-options";
import type { WorkspaceSettings } from "@/lib/settings";
import { INSIGHT_TYPES } from "@/lib/insight-types";
import { SPEECH_ENGINE_LABELS } from "@/lib/ai/speech/engine";
import { saveSettings } from "./actions";
import { SpeechModels } from "./speech-models";
import { SpeechOpenRouter } from "./speech-openrouter";
import type { AiSource } from "@/lib/ai/chatgpt";
import { useAiAccess } from "@/lib/ai/use-ai-access";
import { connectedDefault, modelOptions, type ModelConnections } from "@/lib/ai/model-options";
import { VoiceKeyToast } from "@/components/voice-key-toast";

const input = "min-h-10 min-w-0 w-full rounded-lg border border-border bg-card px-3 py-2 text-sm font-normal text-foreground";
const card = "scroll-mt-20 space-y-4 rounded-xl border border-border bg-card p-6";
const legend = "px-2 text-base font-semibold";
const label = "grid gap-1.5 text-sm font-medium";
const help = "text-sm text-muted-foreground";
const scopeDescriptions = { accounts: "Account names and dated balances", transactions: "Booked transactions, categories and spending evidence",
  planning: "Goals, budgets and forecast assumptions", imports: "Headers and up to eight source rows for import mapping" };

const LOCALES = [["en-GB", "English (United Kingdom)"], ["en-US", "English (United States)"], ["en-IE", "English (Ireland)"], ["de-DE", "German (Germany)"], ["de-AT", "German (Austria)"], ["de-CH", "German (Switzerland)"],
  ["fr-FR", "French (France)"], ["es-ES", "Spanish (Spain)"], ["it-IT", "Italian (Italy)"], ["nl-NL", "Dutch (Netherlands)"], ["pt-PT", "Portuguese (Portugal)"], ["pl-PL", "Polish (Poland)"], ["sv-SE", "Swedish (Sweden)"], ["tr-TR", "Turkish (Turkey)"], ["ur-PK", "Urdu (Pakistan)"]];
const muteLabels: Partial<Record<(typeof INSIGHT_TYPES)[number], string>> = { asset_debt: "asset and debt changes", upcoming_obligations: "upcoming payments" };

function ModelPicker({ name, initial, placeholder, options, invalid, onChange }: { name: string; initial: string; placeholder: string; options: string[]; invalid: object; onChange: () => void }) {
  const [value, setValue] = useState(initial);
  const id = useId();
  const [open, setOpen] = useState(false);
  const [active, setActive] = useState(-1);
  const shown = options.includes(value) ? options : options.filter(model => model.toLowerCase().includes(value.toLowerCase().trim()));
  const choose = (model: string) => { setValue(model); onChange(); setOpen(false); setActive(-1); };
  return <div className="relative" onBlur={event => { if (!event.currentTarget.contains(event.relatedTarget)) setOpen(false); }}>
    <div className="relative">
      <input id={name} role="combobox" aria-expanded={open} aria-controls={id} aria-autocomplete="list"
        aria-activedescendant={open && active >= 0 ? `${id}-${active}` : undefined}
        className={`${input} pr-12`} {...invalid} name={name} value={value} placeholder={placeholder}
        maxLength={200} autoComplete="off" spellCheck={false}
        onFocus={() => setOpen(true)}
        onChange={event => { setValue(event.target.value); setOpen(true); setActive(-1); }}
        onKeyDown={event => {
          if (event.key === "Escape") { event.preventDefault(); setOpen(false); }
          if (event.key === "ArrowDown" || event.key === "ArrowUp") {
            event.preventDefault(); setOpen(true);
            setActive(index => Math.max(0, Math.min(shown.length - 1, index + (event.key === "ArrowDown" ? 1 : -1))));
          }
          if (event.key === "Enter" && open && shown[active]) { event.preventDefault(); choose(shown[active]); }
        }} />
      <button type="button" aria-label={`Show suggestions for ${name}`} aria-expanded={open} aria-controls={id}
        className="absolute inset-y-0 right-0 flex w-10 items-center justify-center rounded-r-lg hover:bg-muted"
        onClick={() => { setOpen(!open); setActive(-1); }}><ChevronDown className="size-4" aria-hidden="true" /></button>
    </div>
    {open && <ul id={id} role="listbox" aria-label="Model suggestions" className="absolute z-20 mt-1 max-h-56 w-full overflow-auto rounded-lg border border-border bg-card p-1 text-sm shadow-lg">
      {shown.map((model, index) => <li key={model} id={`${id}-${index}`} role="option" aria-selected={active === index}
        className={`cursor-pointer break-all rounded-md px-3 py-2 hover:bg-muted ${active === index ? "bg-muted" : ""}`}
        onMouseDown={event => { event.preventDefault(); choose(model); }}>{model}</li>)}
      {!shown.length && <li className="px-3 py-2 text-muted-foreground">Use the model ID you typed.</li>}
    </ul>}
  </div>;
}

function VoicePicker({ value }: { value: WorkspaceSettings["voice"] }) {
  const selectId = useId();
  const [voice, setVoice] = useState(value);
  const [state, setState] = useState<"idle" | "loading" | "playing" | "failed">("idle");
  const [needsKey, setNeedsKey] = useState(false);
  const audio = useRef<HTMLAudioElement | null>(null);
  const access = useAiAccess();
  const stop = () => { audio.current?.pause(); audio.current = null; setState("idle"); };
  useEffect(() => () => audio.current?.pause(), []);
  async function play() {
    if (state === "playing") return stop();
    if (access?.voice === false) return setNeedsKey(true);
    audio.current?.pause();
    setState("loading");
    try {
      const clip = new Audio(`/api/voice/sample?${new URLSearchParams({ voice })}`);
      audio.current = clip;
      clip.onended = () => setState("idle");
      await clip.play();
      setState("playing");
    } catch { setState("failed"); }
  }
  return <div className="grid gap-1.5 text-sm font-medium"><label htmlFor={selectId}>Call voice</label>
    <div className="flex gap-2">
      <select id={selectId} name="voice" className={input} value={voice} onChange={event => { stop(); setVoice(event.target.value as typeof voice); }}>{VOICES.map(name => <option key={name} value={name}>{name[0].toUpperCase() + name.slice(1)}</option>)}</select>
      <button type="button" onClick={() => void play()} disabled={state === "loading"} className="inline-flex min-h-10 shrink-0 items-center gap-2 rounded-lg border border-border px-3 text-sm font-medium transition-colors hover:bg-muted focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ai disabled:opacity-60">
        {state === "loading" ? <Loader2 className="size-4 motion-safe:animate-spin" aria-hidden="true" /> : state === "playing" ? <Square className="size-4 text-ai" aria-hidden="true" /> : <Play className="size-4" aria-hidden="true" />}
        {state === "loading" ? "Loading…" : state === "playing" ? "Stop sample" : "Play sample"}</button>
    </div>
    {needsKey && <VoiceKeyToast onDismiss={() => setNeedsKey(false)} />}
    {state === "failed" && <span role="alert" className="text-sm font-normal text-danger">{"Couldn’t play the sample. Check your sound and try again."}</span>}</div>;
}

const neverChanges = () => () => {};

export function SettingsForm({ settings, currency, timeZones, aiSource, connections }: { settings: WorkspaceSettings; currency: string; timeZones: string[]; aiSource: AiSource; connections: ModelConnections }) {
  const [state, action, pending] = useActionState(saveSettings, {});
  const [customize, setCustomize] = useState(AI_AGENT_KEYS.some(agent => Boolean(settings.ai_models[agent])));
  const [dirty, setDirty] = useState(false);
  const [zone, setZone] = useState(settings.timezone);
  const deviceZone = useSyncExternalStore(neverChanges, deviceTimeZone, () => null);
  const [locale, setLocale] = useState(settings.locale);
  const [speechEngine, setSpeechEngine] = useState(settings.speech_engine);
  const form = useRef<HTMLFormElement>(null);
  const unsaved = dirty || !!state.error;
  const invalid = (name: string) => state.field === name ? { "aria-invalid": true, "aria-describedby": "settings-error" } : {};
  useEffect(() => {
    if (!unsaved) return;
    const warn = (event: BeforeUnloadEvent) => event.preventDefault();
    window.addEventListener("beforeunload", warn);
    return () => window.removeEventListener("beforeunload", warn);
  }, [unsaved]);
  useEffect(() => {
    const named = state.field && form.current?.elements.namedItem(state.field);
    const field = named instanceof HTMLInputElement && named.type === "hidden" ? named.nextElementSibling : named;
    if (!(field instanceof HTMLElement)) return;
    field.closest("details")?.setAttribute("open", "");
    field.focus();
  }, [state]);
  const zones = timeZones.includes(settings.timezone) ? timeZones : [settings.timezone, ...timeZones];
  const locales = LOCALES.some(([code]) => code === settings.locale) ? LOCALES : [[settings.locale, settings.locale], ...LOCALES];
  const example = displayFormat(locale);
  return <form ref={form} action={action} onChange={() => setDirty(true)} onSubmit={() => setDirty(false)} onReset={event => event.preventDefault()} className="space-y-8">
    <fieldset id="display" className={card}><legend className={legend}>Display and calendar</legend>
      <div className="grid gap-3 sm:grid-cols-2">
        <label className={label}>Display currency<CurrencySelect name="display_currency" label="Display currency" defaultValue={currency} locale={settings.locale} onChange={() => setDirty(true)} /></label>
        <div><label className={label}>Timezone<select className={input} name="timezone" value={zone} onChange={event => setZone(event.target.value)} {...invalid("timezone")}>{zones.map(name => <option key={name} value={name}>{name.replaceAll("_", " ")}</option>)}</select></label>
          {deviceZone && deviceZone !== zone && zones.includes(deviceZone) && <button type="button" className="mt-1 text-xs font-medium text-brand hover:underline" onClick={() => { setZone(deviceZone); setDirty(true); }}>Use this device&apos;s timezone ({deviceZone.replaceAll("_", " ")})</button>}</div>
        <label className={label}>Date and number locale<select className={input} name="locale" defaultValue={settings.locale} onChange={event => setLocale(event.target.value)} {...invalid("locale")}>{locales.map(([code, name]) => <option key={code} value={code}>{name}</option>)}</select></label>
        <label className={label}>Appearance<select className={input} name="theme" defaultValue={settings.theme}><option value="system">Follow device</option><option value="light">Light</option><option value="dark">Dark</option></select></label>
      </div><p className={help}>Dates and numbers will look like {example.longDate("2026-01-31")} and {example.money(123456, currency)}.</p>
      <p className={help}>Totals are converted to your display currency using the rates available. Your original currencies and amounts are never changed. The app is available in English only.</p>
    </fieldset>
    <fieldset id="ai" className={card}><legend className={legend}>AI and your data</legend>
      <p className={help}>Choose which of your data the AI may use. Secrets are never sent.</p>
      <div className="space-y-4 border-t border-border pt-4">
        <div className={label}><label htmlFor="model:default">Default model</label>
          <ModelPicker onChange={() => setDirty(true)} invalid={invalid("model:default")} name="model:default" initial={settings.ai_models.default ?? ""}
            placeholder={connectedDefault("chat", connections, aiSource === "claude")} options={modelOptions(connections)} />
          <p className={help}>Used for every AI task. Type a model ID or choose a suggestion. Leave blank for the default shown.</p>
        </div>
        <label className="flex items-center gap-2 text-sm font-medium"><input type="checkbox" className="size-4" checked={customize} onChange={event => setCustomize(event.target.checked)} />Customize by task</label>
        <fieldset disabled={!customize} hidden={!customize} className="grid gap-3 sm:grid-cols-2">{AI_AGENT_KEYS.map(agent => <div key={agent} className={label}>
          <label htmlFor={`model:${agent}`}>{AI_AGENTS[agent].label} model</label>
          <ModelPicker onChange={() => setDirty(true)} invalid={invalid(`model:${agent}`)} name={`model:${agent}`} initial={settings.ai_models[agent] ?? ""}
            placeholder="Use default model" options={modelOptions(connections)} />
        </div>)}</fieldset>
        <p className={help}>OpenRouter IDs include vendor/model. Saving does not call the AI provider.</p>
      </div>
      <details className="text-sm text-muted-foreground"><summary className="cursor-pointer">More details</summary><p className="mt-2">OpenAI, Anthropic or OpenRouter (depending on the model) receives your prompts and only the enabled data needed for the task. Chat never receives raw statement files. Import mapping may send column headers and up to eight sample rows. Usage is billed to the matching API key, or counts toward your ChatGPT or Claude plan.</p></details>
      <div className="divide-y divide-border">{AI_DATA_SCOPES.map(scope => <label key={scope} className="flex items-start gap-3 py-3 text-sm"><input type="checkbox" className="mt-1 size-4" name="ai_data_scopes" value={scope} defaultChecked={settings.ai_data_scopes.includes(scope)} /><span><strong className="block capitalize">{scope}</strong><span className="text-muted-foreground">{scopeDescriptions[scope]}</span></span></label>)}</div>
    </fieldset>
    <fieldset id="voice" className={card}><legend className={legend}>Voice</legend>
      <VoicePicker value={settings.voice} />
      <label className={label}>Speech to text
        <select name="speech_engine" className={input} value={speechEngine} onChange={event => setSpeechEngine(event.target.value as typeof speechEngine)}>
          {SPEECH_ENGINES.map(engine => <option key={engine} value={engine} disabled={engine === "openrouter" && !connections.openrouter && engine !== settings.speech_engine}>{SPEECH_ENGINE_LABELS[engine]}{engine === "openrouter" && !connections.openrouter ? " (needs an OpenRouter key)" : ""}</option>)}
        </select>
        <span className={`${help} font-normal`}>Turns what you say into text when you use the microphone in chat. Voice calls always use OpenAI. If the engine you choose can&apos;t run, Moneo uses OpenAI when you have added an API key.</span>
      </label>
      <SpeechOpenRouter initial={settings.speech_openrouter_model} hidden={speechEngine !== "openrouter"} onChange={() => setDirty(true)} />
      <SpeechModels initial={settings.speech_local_model} hidden={speechEngine !== "local"} onChange={() => setDirty(true)} />
    </fieldset>
    <fieldset id="insights" className={card}><legend className={legend}>Insights and summaries</legend>
      <p className={help}>Mute the insight types you do not want to see.</p>
      <div className="grid gap-3 sm:grid-cols-2">{INSIGHT_TYPES.map(type => <label key={type} className="flex items-center gap-2 text-sm"><input type="checkbox" name="muted_insight_types" value={type} defaultChecked={settings.muted_insight_types.includes(type)} /><span>Mute {muteLabels[type] ?? type.replaceAll("_", " ")}</span></label>)}</div>
      <div className="grid gap-3 sm:grid-cols-2"><label className="grid gap-1.5 text-sm font-medium">In-app summary preference<select className={input} name="summary_cadence" defaultValue={settings.summary_cadence}><option value="none">Off</option><option value="weekly">Weekly</option><option value="monthly">Monthly</option></select></label><label className={label}>Preferred local time<input className={input} type="time" name="summary_time" defaultValue={settings.summary_time} required {...invalid("summary_time")} /></label></div>
      <p className={help}>Summaries appear in the Activity log and may arrive up to a day late.</p>
    </fieldset>
    <div className="sticky bottom-20 z-10 max-lg:bottom-[calc(4rem+env(safe-area-inset-bottom))] space-y-2 rounded-xl border border-border bg-card p-3 shadow-sm lg:bottom-4">
      {state.error && !pending && <p id="settings-error" role="alert" className="rounded-lg border border-danger/40 bg-danger-soft p-3 text-sm text-danger">{state.error}</p>}
      <div className="flex flex-wrap items-center gap-3">
        <button disabled={pending} className="min-h-10 rounded-lg bg-primary px-5 py-2 text-sm font-medium text-primary-foreground disabled:opacity-60">{pending ? "Saving…" : "Save preferences"}</button>
        {pending ? <span className="text-sm text-muted-foreground">Saving your preferences...</span>
          : dirty ? <span className="text-sm text-warning">Unsaved changes</span>
          : state.saved ? <p role="status" className="text-sm text-success">Preferences saved.</p> : null}
      </div>
    </div>
  </form>;
}
"use server";

import { cookies } from "next/headers";
import { revalidatePath } from "next/cache";
import { redirect } from "next/navigation";
import { z } from "zod";
import { requireWorkspace } from "@/lib/auth";
import { AI_AGENT_KEYS, settingsSchema } from "@/lib/settings";
import { minorDigits } from "@/lib/finance/fx";
import { revokeBankSessions } from "@/lib/bank/server";

export type SaveSettingsState = { error?: string; field?: string; saved?: boolean };

export async function saveSettings(_previous: SaveSettingsState, form: FormData): Promise<SaveSettingsState> {
  let field: string | undefined;
  try {
    const { supabase, workspace, settings: current } = await requireWorkspace();
    const settings = settingsSchema.parse({
      timezone: form.get("timezone"), locale: form.get("locale"), theme: form.get("theme"), voice: form.get("voice"), speech_engine: form.get("speech_engine") ?? undefined,
      speech_local_model: String(form.get("speech_local_model") ?? "").trim() || null,
      speech_openrouter_model: String(form.get("speech_openrouter_model") ?? "").trim() || null,
      ai_models: Object.fromEntries(["default", ...AI_AGENT_KEYS].map(agent => [agent, String(form.get(`model:${agent}`) ?? "").trim()]).filter(([, model]) => model)),
      ai_data_scopes: form.getAll("ai_data_scopes"), muted_insight_types: form.getAll("muted_insight_types"),
      summary_cadence: form.get("summary_cadence"), summary_time: form.get("summary_time"),
      artifact_scalable_data: current.artifact_scalable_data,
    });
    field = "display_currency";
    const currency = z.string().trim().toUpperCase().regex(/^[A-Z]{3}$/, "Use a three-letter currency code, such as EUR").parse(form.get("display_currency"));
    minorDigits(currency);
    field = undefined;
    const result = await supabase.rpc("save_workspace_preferences", { p_workspace_id: workspace.id, p_display_currency: currency, p_preferences: settings });
    if (result.error) {
      console.error("Preferences save failed", { code: result.error.code });
      throw new Error("Preferences could not be saved. Run setup to apply database updates, then try again.");
    }
    (await cookies()).set("moneo-theme", settings.theme, { httpOnly: true, sameSite: "lax", path: "/", maxAge: 31536000 });
    revalidatePath("/", "layout");
    return { saved: true };
  } catch (error) {
    const zodField = error instanceof z.ZodError ? error.issues[0]?.path[0] : undefined;
    return { error: error instanceof z.ZodError ? error.issues.map(issue => issue.message).join(". ") : error instanceof Error ? error.message : "Preferences could not be saved",
      field: typeof zodField === "string" ? zodField : field };
  }
}

async function removeWorkspaceFiles({ supabase, workspace }: Awaited<ReturnType<typeof requireWorkspace>>) {
  for (const bucket of ["imports", "chat"]) {
    for (;;) {
      const listed = await supabase.storage.from(bucket).list(workspace.id, { limit: 1000 });
      if (listed.error) throw listed.error;
      if (!listed.data.length) break;
      const removed = await supabase.storage.from(bucket).remove(listed.data.map(file => `${workspace.id}/${file.name}`));
      if (removed.error) throw removed.error;
      if (!removed.data.length) break;
    }
  }
}

export async function resetAllData(_previous: { error?: string }, form: FormData): Promise<{ error?: string }> {
  try {
    const context = await requireWorkspace();
    if (!z.literal("RESET").safeParse(form.get("confirmation")).success) return { error: "Type RESET to confirm" };
    await removeWorkspaceFiles(context);
    await revokeBankSessions(context.workspace.id);
    const result = await context.supabase.rpc("reset_workspace");
    if (result.error) throw result.error;
  } catch {
    return { error: "Your data could not be reset completely. Some files or bank connections may already be gone, so try again to finish." };
  }
  revalidatePath("/", "layout");
  redirect("/");
}
