import { chromium } from "@playwright/test";
const browser = await chromium.launch();
const median = list => list.sort((a, b) => a - b)[Math.floor(list.length / 2)];
for (const [label, port] of [["before", 3102], ["after", 3101]]) {
  const page = await browser.newPage({ storageState: "e2e/.auth.json", extraHTTPHeaders: { "x-moneo-test": "1" } });
  await page.goto(`http://localhost:${port}/settings`);
  const times = [];
  for (let run = 0; run < 6; run++) {
    const theme = run % 2 ? "system" : "light";
    const t0 = Date.now();
    await page.getByRole("combobox", { name: "Appearance" }).selectOption(theme);
    if (label === "before") { await page.getByRole("button", { name: "Save preferences" }).click(); await page.getByRole("status").filter({ hasText: "Preferences saved" }).waitFor(); }
    else await page.locator("#general").getByRole("status").filter({ hasText: "Saved" }).waitFor();
    if (run) times.push(Date.now() - t0);
    await page.waitForTimeout(300);
  }
  console.log(label, median(times), times.join(","));
}
await browser.close();
EOF
